import dataFoundations from 'theme/colors/dataFoundations';

export const PERFORMANCE_TOOL_PAGE_NAME = 'value-creation_performance-tool';

export const PERFORMANCE_TOOL_NAVIGATION_TEST_ID =
  'performance-tool-navigation';

export { STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX as PERFORMANCE_SECTION_STICKY_TOP_OFFSET_FALLBACK_PX } from 'hooks/useStickyNavigationTopOffset/constants';

const { series, waterfall } = dataFoundations.charts.bg;
const { comparison: comparisonStatus } = dataFoundations.charts.txt.status;

export const VALUE_CREATION_LINE_BAR_CHART_COLORS = {
  lastYear: series.lastYear,
  budget: series.budget,
  current: series.current,
};

export const VALUE_CREATION_TREND_COLORS = {
  positive: comparisonStatus.positive,
  negative: comparisonStatus.negative,
  neutral: comparisonStatus.neutral,
};

export const WATERFALL_COLORS = {
  first: waterfall.first,
  last: waterfall.last,
  positive: waterfall.positive,
  negative: waterfall.negative,
};

export const MARKET_SHARE_COUNTRIES_WITHOUT_BRAND_DATA = ['GTM', 'URY', 'ZMB'];

export const PERFORMANCE_TOOL_PATH = '/value-creation/performance-tool';

export const WATERFALL_RESET_EVENT = 'waterfall:filter-reset';
